See the [contributing guide](https://mise.jdx.dev/contributing).

## mbx build cache

`mise install` installs [mbx](https://mr-boxington.jdx.dev) at the version pinned in `mise.toml`. The normal
`mise run build`, `mise run test:unit`, and `mise run lint` workflows activate
its transparent Cargo wrapper and therefore use the cache while invoking Cargo
normally. Standalone Cargo commands require an activated mise shell. To bypass
mbx without skipping or weakening a check, prefix the
equivalent Cargo command with `MBX_DISABLE=1`:

```sh
MBX_DISABLE=1 cargo build --all-features
MBX_DISABLE=1 cargo test --all-features
MBX_DISABLE=1 cargo check --all-features
```

If bypassed Cargo succeeds where the wrapper fails, or mbx introduces a papercut, please start a
[mr-boxington Discussion](https://github.com/jdx/mr-boxington/discussions).
Include the repository and commit, operating system, `mbx --version`,
`mbx doctor`, and both commands and their output. Before posting, redact
secrets, absolute cache paths, remote URLs, namespaces, and other sensitive or
identifying details.
amends "package://github.com/jdx/hk/releases/download/v2.0.0/hk@2.0.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v2.0.0/hk@2.0.0#/Builtins.pkl"

local bash_glob = List("*.sh", "xtasks/**", "scripts/**", "e2e/**")
local bash_exclude = List("*.ps1", "**/*.fish", "*.ts", "*.js", "*.json", "*.bat", "**/.*", "src/assets/bash_zsh_support/**", "e2e/shell/xonsh_script", "tmp/install.sh", "**/*.py", "**/*.xsh")
local linters = new Mapping<String, Step> {
    ["schema"] {
        glob = List("schema/**/*.json")
        stdin = "{{ files_list | join(sep='\u{0}') }}"
        check = new CommandSpec {
          command = "xargs -0 -I {} ajv compile -s {} --spec=draft2020 --strict-types=true --strict-tuples=true"
          effect = "read"
        }
        check_first = false
    }
    // uses builtin prettier linter config; run via `mise x` so hk picks up
    // the mise-pinned prettier rather than whatever happens to be on
    // PATH (e.g. a Homebrew prettier), keeping local and CI in sync.
    ["prettier"] = (Builtins.prettier) {
      batch = false
      exclude = "vendor/aqua-registry/**"
      check = new CommandSpec {
        command = "mise x prettier -- prettier --check {{ files }}"
        effect = "read"
      }
      check_list_files = new CommandSpec {
        command = "mise x prettier -- prettier --list-different {{ files }}"
        effect = "read"
      }
      fix = new CommandSpec {
        command = "mise x prettier -- prettier --write {{ files }}"
        effect = "write"
      }
      depends = List("schema")
    }
    //["clippy"] = (Builtins.cargo_clippy) {
    //  check = "cargo clippy --manifest-path {{workspace_indicator}} --all-features -- -Dwarnings"
    //  fix = "cargo clippy --manifest-path {{workspace_indicator}} --all-features --fix --allow-dirty --allow-staged -- -Dwarnings"
    //}
    ["cargo-fmt"] {
      glob = List("**/*.rs")
      check = new CommandSpec {
        command = "cargo fmt --all -- --check"
        effect = "read"
      }
      fix = new CommandSpec {
        command = "cargo fmt --all"
        effect = "write"
      }
    }
    ["cargo-check"] = (Builtins.cargo_check) {
      check = new CommandSpec {
        command = "cargo check --all-features"
        effect = "write"
      }
    }
    ["shellcheck"] = (Builtins.shellcheck) {
      match_any = null
      glob = bash_glob
      exclude = bash_exclude
      batch = true
      check = new CommandSpec {
        command = "shellcheck -x {{ files }}"
        effect = "read"
      }
    }
    ["shfmt"] = (Builtins.shfmt) {
      match_any = null
      check_list_files = new CommandSpec {
        command = """
files=$(shfmt -l -s {{ files }})
if [ -n "$files" ]; then
  echo "$files"
  exit 1
fi
"""
        effect = "read"
      }
      fix = new CommandSpec {
        command = "shfmt -w -s {{ files }}"
        effect = "write"
      }
      glob = bash_glob
      exclude = bash_exclude
    }

    // uses taplo for TOML formatting and validation
    ["taplo"] {
        glob = List("**/*.toml")
        check = new CommandSpec {
          command = "taplo fmt --check {{files}} && taplo check {{files}}"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "taplo fmt {{files}} && taplo check {{files}}"
          effect = "write"
        }
    }

    // uses lua-language-server to check vfox test plugin Lua files
    // excludes embedded-plugins/ which are vendored from external repos
    ["lua-check"] {
        glob = List("crates/vfox/plugins/**/*.lua")
        check = new CommandSpec {
          command = "lua-language-server --check crates/vfox/plugins/"
          effect = "write"
        }
    }
    ["stylua"] {
        glob = List("crates/vfox/plugins/**/*.lua")
        check = new CommandSpec {
          command = "stylua --check crates/vfox/plugins/"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "stylua crates/vfox/plugins/"
          effect = "write"
        }
    }
    ["markdownlint"] {
        glob = List("**/*.md")
        check = new CommandSpec {
          command = "markdownlint {{ files }}"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "markdownlint --fix {{ files }}"
          effect = "write"
        }
    }
}

hooks {
    ["fix"] {
        fix = true
        steps = linters
    }
    ["check"] {
        steps = linters
    }
}
